"""Hand-worked traces and actual intermediate SQL relations."""
import sqlite3

TRACES = {
'prefix': ('Построение префиксов для [3, −2, 5, 1]', ['Число обработанных элементов','Добавленное значение','Префикс'], [['0','—','0'],['1','3','3'],['2','−2','1'],['3','5','6'],['4','1','7']], 'Нулевой префикс соответствует пустому началу. Каждая следующая строка добавляет ровно один элемент. Для [1,3) вычитаются значения строк 3 и 1: 6−3=3. Для [2,2) берётся разность одной и той же суммы, поэтому ответ ноль без специального обхода.'),
'window': ('Окно после восстановления допустимости', ['right','left','Сумма окна','Лучшая длина'], [['0','0','2','1'],['1','0','3','2'],['2','1','4','2'],['3','2','4','2']], 'Таблица относится к [2,1,3,1] и k=4. На третьем элементе сумма сначала становится 6, затем удаление 2 восстанавливает 4. На последнем элементе сумма 5 требует удаления 1. Левая граница не возвращается назад; это позволяет суммировать общую работу двух циклов.'),
'kadane': ('Лучший отрезок, заканчивающийся в текущей позиции', ['i','Элемент','ending','best'], [['0','−2','−2','−2'],['1','3','3','3'],['2','−1','2','3'],['3','4','6','6'],['4','−5','1','6']], 'ending и best отвечают на разные вопросы. После последнего элемента лучший заканчивающийся здесь отрезок имеет сумму 1, но лучший за весь просмотренный массив по-прежнему равен 6. Возврат одного ending вместо best потерял бы уже найденное решение.'),
'capacity': ('Границы до очередной проверки вместимости', ['low','high','middle','Нужно групп'], [['10','32','21','2'],['10','21','15','3'],['16','21','18','2'],['16','18','17','3']], 'Для [7,2,5,10,8] и k=2 допустимая середина становится новой верхней границей. Недопустимая исключается вместе со всеми меньшими значениями. После последней строки low=high=18. У каждого изменения есть основание в монотонности, а не только традиционный шаблон двоичного поиска.'),
'coins': ('Состояния точной суммы для номиналов 1, 3 и 4', ['Сумма','Минимальное число монет'], [['0','0'],['1','1'],['2','2'],['3','1'],['4','1'],['5','2'],['6','2']], 'Для суммы 6 рассматриваются последние монеты 1,3,4. Кандидат через 3 использует уже решённую сумму 3 и даёт две монеты. Жадный выбор 4 сразу не гарантирует такого результата. Различай достижимость состояния и его оптимальное значение.'),
'lis': ('Состояния для [3,1,2,5,4]', ['i','a[i]','dp[i]'], [['0','3','1'],['1','1','1'],['2','2','2'],['3','5','3'],['4','4','3']], 'Каждая строка требует рассмотреть только меньшие позиции с меньшими значениями. Элемент 4 может продолжить [1,2], но не [1,2,5]. Ответ 3 сохраняется, хотя последнее значение отличается от ранее выбранного хвоста. Таблица длин ещё не является самой восстановленной подпоследовательностью.'),
'bfs': ('Состояние после обработки извлечённой вершины', ['Вершина','Оставшаяся очередь','Расстояния 0…3'], [['0','1, 2','0, 1, 1, −1'],['1','2, 3','0, 1, 1, 2'],['2','3','0, 1, 1, 2'],['3','пусто','0, 1, 1, 2']], 'Вершина 3 получает расстояние при первом добавлении, поэтому второй путь через 2 не ставит её в очередь снова. Обратное ребро в 0 не разрушает завершение: старт уже отмечен. Очередь является частью доказательства порядка слоёв.'),
'dijkstra': ('Завершение минимальной ещё не обработанной вершины', ['Выбранная вершина','Расстояния 0…2'], [['0','0, 10, 2'],['2','0, 5, 2'],['1','0, 5, 2']], 'Предварительное расстояние 10 до вершины 1 улучшается через 2 до 5. Окончательность связана с выбором минимальной незавершённой вершины, а не первым обнаружением. Взвешенный граф требует такого различия; для отрицательных рёбер это доказательство уже не действует.'),
}

PHASES = {
'islands':[('unique_days','Удалены повторные посещения одного дня; одна строка — пользователь и уникальный день.'),('numbered','Появился ключ острова day−row_number. Одинаковый ключ внутри пользователя связывает непрерывные дни.')],
'sessions':[('previous','Предыдущее время вычислено отдельно для пользователя в порядке minute,id.'),('starts','Признак fresh равен единице на первой записи и после разрыва больше 30.'),('numbered','Накопленная сумма fresh задаёт номер сессии, не удаляя отдельные события.')],
'cohorts':[('activity','Несколько событий одного пользователя за месяц сведены к одному факту активности.'),('firsts','Для каждого пользователя вычислен месяц первой активности.'),('measured','Каждый факт активности получает номер месяца относительно собственной когорты.')],
'hierarchy':[('tree','Каждая достигнутая запись хранит глубину и путь. Самоссылочный компонент без корня не входит в результат этого обхода.')],
'reachability':[('reached','Отношение хранит только разные номера вершин; UNION останавливает повторные обходы цикла.')],
'division':[('required','Набор требований отделён от завершений; пустой набор имел бы особый универсальный смысл.'),('completed','Повтор завершения остаётся фактом входа, но не должен заменять выполнение другого требования.')],
'pareto':[('totals','Детальные продажи сведены к одной строке на категорию.'),('measured','К каждой категории добавлены общий итог и накопительная сумма в выбранном полном порядке.')],
'ledger':[('balances','Каждая проводка сохранена; баланс вычислен после неё внутри своего счёта.')],
}


def algorithm_trace(slug):
    title,columns,rows,text=TRACES[slug]
    return {'heading':'Пошаговая таблица: '+title,'text':text,'table':{'columns':columns,'rows':rows}}


def sql_phases(slug, query):
    prefix=query[:query.rfind('\nSELECT')]
    assert prefix and prefix!=query
    db=sqlite3.connect(':memory:');sections=[]
    for name,explanation in PHASES[slug]:
        cursor=db.execute(prefix+'\nSELECT * FROM '+name)
        columns=[c[0] for c in cursor.description]
        # Query again with a fully stated display order, independent of plan.
        cursor=db.execute(prefix+'\nSELECT * FROM '+name+' ORDER BY '+','.join(str(i+1) for i in range(len(columns))))
        rows=cursor.fetchall()
        sections.append({'heading':'Промежуточный этап: '+name,'text':explanation+'\n\nЗдесь '+str(len(rows))+' строк. Сверь их с предыдущим этапом: какие факты сохранены, какие объединены, какие новые значения вычислены? Названия столбцов ниже — реальные имена текущего отношения. Для независимой проверки измени один исходный факт и заранее предскажи затронутые строки. Не путай порядок показа этой таблицы с оконным порядком вычисления.','table':{'columns':columns,'rows':[['NULL' if v is None else str(v) for v in row] for row in rows]}})
    db.close();return sections
